def mobile_list_available_devices(deviceType=None, status=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0522000" if __import__("os").path.isdir("./environment_mix/0522000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- rate/quota + audit (session_actions) ----
    actions = _load("session_actions.json")
    sessions = _load("sessions.json")
    devices = _load("devices.json")

    # Determine "caller context" as the most recent active session, if any
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    active_sessions.sort(key=lambda s: (s.get("updated_at") or s.get("created_at") or ""), reverse=True)
    caller_session = active_sessions[0] if active_sessions else None
    caller_session_id = caller_session.get("id") if caller_session else None
    caller_device_id = caller_session.get("device_id") if caller_session else None

    def _enforce_limits():
        # very simple local limits: 60 calls/min globally; 2000 calls/day globally
        minute_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        day_ago = (datetime.datetime.utcnow() - datetime.timedelta(days=1)).replace(microsecond=0).isoformat() + "Z"
        def _ts(a):
            return a.get("created_at") or a.get("updated_at") or ""
        last_min = [a for a in actions if isinstance(a, dict) and _ts(a) >= minute_ago]
        last_day = [a for a in actions if isinstance(a, dict) and _ts(a) >= day_ago]
        if len(last_min) >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit_per_minute=60)
        if len(last_day) >= 2000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded. Try again later.", quota_per_day=2000)
        return None

    limit_check = _enforce_limits()
    action_row = None
    action_id = None

    def _new_id(prefix):
        raw = f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{time.time_ns()}"
        return raw

    action_id = _new_id("act")
    action_row = {
        "id": action_id,
        "session_id": caller_session_id or "anonymous",
        "device_id": caller_device_id or "unknown",
        "tool_name": "mobile_list_available_devices",
        "status": "running",
        "input": {
            "deviceType": deviceType,
            "status": status,
            "limit": limit,
            "cursor": cursor,
            "sortBy": sortBy,
            "sortOrder": sortOrder
        },
        "error_code": None,
        "error_message": None,
        "result": None,
        "screenshot_artifact_id": None,
        "ui_snapshot_artifact_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now
    }
    actions.append(action_row)
    _save("session_actions.json", actions)

    def _finish(success, result=None, err=None):
        end = time.time()
        duration_ms = int(round((end - t0) * 1000))
        a = None
        for r in actions:
            if isinstance(r, dict) and r.get("id") == action_id:
                a = r
                break
        if a:
            a["duration_ms"] = duration_ms
            a["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            if success:
                a["status"] = "succeeded"
                a["result"] = result
                a["error_code"] = None
                a["error_message"] = None
            else:
                a["status"] = "failed"
                a["result"] = None
                a["error_code"] = err["error"]["code"] if err and "error" in err else "failed"
                a["error_message"] = err["error"]["message"] if err and "error" in err else "Request failed"
        _save("session_actions.json", actions)
        return result if success else err

    if limit_check:
        return _finish(False, err=limit_check)

    # ---- validate inputs ----
    allowed_device_types = {"simulator", "ios", "android"}
    allowed_statuses = {"available", "reserved", "busy", "offline", "disabled"}
    allowed_sort_by = {"display_name", "device_type", "platform_version", "hardware_model", "status", "last_seen_at", "created_at", "updated_at"}
    allowed_sort_order = {"asc", "desc"}

    if deviceType is not None and (not isinstance(deviceType, str) or deviceType not in allowed_device_types):
        return _finish(False, err=_err("VALIDATION_ERROR", "Invalid deviceType.", allowed=list(sorted(allowed_device_types))))
    if status is not None and (not isinstance(status, str) or status not in allowed_statuses):
        return _finish(False, err=_err("VALIDATION_ERROR", "Invalid status.", allowed=list(sorted(allowed_statuses))))
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _finish(False, err=_err("VALIDATION_ERROR", "Invalid limit. Must be between 1 and 200."))
    if sortBy is None:
        sortBy = "display_name"
    if not isinstance(sortBy, str) or sortBy not in allowed_sort_by:
        return _finish(False, err=_err("VALIDATION_ERROR", "Invalid sortBy.", allowed=list(sorted(allowed_sort_by))))
    if sortOrder is None:
        sortOrder = "asc"
    if not isinstance(sortOrder, str) or sortOrder not in allowed_sort_order:
        return _finish(False, err=_err("VALIDATION_ERROR", "Invalid sortOrder.", allowed=list(sorted(allowed_sort_order))))

    # cursor format: base64url(json: {"o": offset, "h": hash_of_query})
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            return _finish(False, err=_err("VALIDATION_ERROR", "Malformed cursor."))
        try:
            pad = "=" * (-len(cursor) % 4)
            payload = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(payload)
            if not isinstance(obj, dict) or "o" not in obj or "h" not in obj:
                return _finish(False, err=_err("VALIDATION_ERROR", "Malformed cursor."))
            if not isinstance(obj["o"], int) or obj["o"] < 0:
                return _finish(False, err=_err("VALIDATION_ERROR", "Malformed cursor."))
            offset = obj["o"]
            # validate cursor matches current query
            q = {"deviceType": deviceType, "status": status, "sortBy": sortBy, "sortOrder": sortOrder}
            h = hashlib.sha256(json.dumps(q, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
            if obj["h"] != h:
                return _finish(False, err=_err("VALIDATION_ERROR", "Cursor does not match query."))
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            return _finish(False, err=_err("VALIDATION_ERROR", "Malformed cursor."))

    # ---- business rule filtering ----
    # base pool: exclude offline/disabled; include available/reserved only
    pool = []
    for d in devices:
        if not isinstance(d, dict):
            continue
        st = d.get("status")
        if st in ("offline", "disabled"):
            continue
        if st not in ("available", "reserved"):
            continue
        if st == "available":
            pool.append(d)
        else:
            # reserved devices only visible if reserved by caller active session context
            if caller_session and caller_session.get("device_id") == d.get("id") and caller_session.get("status") == "active":
                pool.append(d)

    if deviceType is not None:
        pool = [d for d in pool if d.get("device_type") == deviceType]
    if status is not None:
        # status filter applies after visibility rule; e.g. reserved will still only show caller's reserved device
        pool = [d for d in pool if d.get("status") == status]

    total = len(pool)

    # sorting
    def _k(v):
        if v is None:
            return ""
        if isinstance(v, (int, float)):
            return v
        return str(v)

    reverse = (sortOrder == "desc")
    pool.sort(key=lambda d: _k(d.get(sortBy)), reverse=reverse)

    page = pool[offset: offset + limit]
    has_more = offset + limit < total

    # next cursor
    next_cursor = None
    if has_more:
        q = {"deviceType": deviceType, "status": status, "sortBy": sortBy, "sortOrder": sortOrder}
        h = hashlib.sha256(json.dumps(q, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
        nxt = {"o": offset + limit, "h": h}
        next_cursor = base64.urlsafe_b64encode(json.dumps(nxt, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    result = {
        "devices": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sortBy": sortBy,
        "sortOrder": sortOrder
    }
    return _finish(True, result=result)

def mobile_use_device(device, deviceType, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0522000" if __import__("os").path.isdir("./environment_mix/0522000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _utcnow_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _duration_ms():
        return int((time.time() - t0) * 1000)
    def _new_id(prefix):
        # store examples: mob_sess_01J...
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        def _base32(n):
            if n == 0: return "0"
            s = ""
            while n:
                n, r = divmod(n, 32)
                s = alphabet[r] + s
            return s
        rand = int.from_bytes(os.urandom(8), "big")
        return f"{prefix}_{_base32(ms)}{_base32(rand)}"

    # Validate
    if not isinstance(device, str) or not device.strip():
        return _err("VALIDATION_ERROR", "device must be a non-empty string")
    if not isinstance(deviceType, str) or deviceType not in ("simulator", "ios", "android"):
        return _err("VALIDATION_ERROR", "deviceType must be one of: simulator, ios, android")
    device_req = device.strip()
    device_type_req = deviceType

    devices = _load("devices.json")
    sessions = _load("sessions.json")

    # Find matching device by (display_name, device_type). If none, try a practical fallback:
    # Many callers pass generic names like "simulator" which may not equal display_name in the pool.
    candidates = [d for d in devices if isinstance(d, dict) and d.get("device_type") == device_type_req]
    exact = [d for d in candidates if d.get("display_name") == device_req]
    if exact:
        match_pool = exact
    else:
        # fallback: allow selecting any available device of that type when device is a generic token
        # This relaxes matching to align with real-world "give me a simulator" usage.
        if device_req.lower() in ("simulator", "ios", "android", "any", "default"):
            match_pool = candidates
        else:
            match_pool = []

    if not match_pool:
        return _err("NOT_FOUND", "No device matches the provided identifier and type.", device=device_req, deviceType=device_type_req)

    # Choose an allocatable device: must be available, not offline/disabled; and no active session already on it.
    def _has_active_session(dev_id):
        for s in sessions:
            if isinstance(s, dict) and s.get("device_id") == dev_id and s.get("status") == "active":
                return True
        return False

    alloc = []
    for d in match_pool:
        if not isinstance(d, dict):
            continue
        st = d.get("status")
        if st != "available":
            continue
        if _has_active_session(d.get("id")):
            continue
        alloc.append(d)

    if not alloc:
        # Distinguish "exists but not allocatable" from not found
        # Report the first candidate's status for debug.
        sample = next((d for d in match_pool if isinstance(d, dict)), None)
        return _err(
            "CONFLICT",
            "Device is not available for reservation. Business rule: mobile_use_device requires device.status='available' and no existing active session for that device.",
            device_status=(sample.get("status") if sample else None),
        )

    # deterministic pick: oldest updated_at (or created_at) first to spread load
    def _k(d):
        return (d.get("updated_at") or d.get("created_at") or "", d.get("id") or "")
    alloc.sort(key=_k)
    dev = alloc[0]

    # Atomic mutation: verify again using current in-memory snapshots then write both files.
    now = _utcnow_iso()
    dev_id = dev.get("id")
    if not dev_id:
        return _err("CONFLICT", "Device record is missing id and cannot be reserved.")
    if dev.get("status") != "available":
        return _err("CONFLICT", "Device is not available for reservation (must be 'available').", device_status=dev.get("status"))
    if _has_active_session(dev_id):
        return _err("CONFLICT", "Device already has an active session and cannot be reserved.", device_id=dev_id)

    sess_id = _new_id("mob_sess")
    session_row = {
        "id": sess_id,
        "device_id": dev_id,
        "requested_device_name": device_req,
        "requested_device_type": device_type_req,
        "status": "active",
        "selected_at": now,
        "ended_at": None,
        "last_action_at": now,
        "current_app_package": None,
        "created_at": now,
        "updated_at": now,
    }

    # Apply device transition available -> reserved (must be legal)
    # lifecycle transitions: available -> reserved allowed
    if dev.get("status") != "available":
        return _err("INVALID_TRANSITION", "Device status transition is not allowed.", from_status=dev.get("status"), to_status="reserved")
    dev["status"] = "reserved"
    dev["updated_at"] = now

    sessions.append(session_row)
    _save("sessions.json", sessions)
    _save("devices.json", devices)

    return {
        "session": dict(session_row),
        "device": dict(dev),
        "result": {
            "session_id": sess_id,
            "device_id": dev_id,
            "device": dev.get("display_name"),
            "deviceType": dev.get("device_type"),
            "duration_ms": _duration_ms(),
        },
    }

def mobile_list_apps(includeSystemApps=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0522000" if __import__("os").path.isdir("./environment_mix/0522000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _duration_ms():
        return int((time.time() - t0) * 1000)

    def _new_id(prefix):
        # Simple, stable enough for local datastore
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{time.time_ns()}"

    # Validate inputs
    if includeSystemApps is not None and not isinstance(includeSystemApps, bool):
        return _err("VALIDATION_ERROR", "includeSystemApps must be a boolean")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    allowed_sort_by = ["display_name", "package_name", "version_name", "version_code", "is_system_app", "last_scanned_at", "created_at", "updated_at"]
    if sortBy is None:
        sortBy = "display_name"
    if not isinstance(sortBy, str) or sortBy not in allowed_sort_by:
        return _err("VALIDATION_ERROR", "sortBy must be one of the allowed fields", allowed=allowed_sort_by)
    if sortOrder is None:
        sortOrder = "asc"
    if not isinstance(sortOrder, str) or sortOrder not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sortOrder must be 'asc' or 'desc'")

    sessions = _load("sessions.json")
    devices = _load("devices.json")
    apps = _load("device_apps.json")
    actions = _load("session_actions.json")

    # Resolve an active session pointing to a real device (ambient auth)
    device_by_id = {d.get("id"): d for d in devices if isinstance(d, dict) and d.get("id")}
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and s.get("id") and s.get("device_id")]
    if not active_sessions:
        return _err("CONFLICT", "No device selected (no active session). Business rule: device-driving tools require an active session.")
    active_sessions.sort(key=lambda s: (s.get("last_action_at") or s.get("updated_at") or s.get("selected_at") or s.get("created_at") or ""), reverse=True)

    session = None
    device = None
    for s in active_sessions:
        d = device_by_id.get(s.get("device_id"))
        if d:
            session, device = s, d
            break
    if not session or not device:
        return _err("NOT_FOUND", "Selected device for the active session no longer exists.")

    # Device readiness checks
    if device.get("status") in ("offline", "disabled"):
        return _err("CONFLICT", "Selected device is not ready (offline/disabled). Business rule: device-driving tools cannot run when device is offline/disabled.", device_id=device.get("id"), device_status=device.get("status"))

    # Record action (required for device-driving tools)
    now = _now()
    action = {
        "id": _new_id("mob_act"),
        "session_id": session.get("id"),
        "device_id": device.get("id"),
        "tool_name": "mobile_list_apps",
        "status": "running",
        "input": {
            "includeSystemApps": includeSystemApps,
            "limit": limit,
            "cursor": cursor,
            "sortBy": sortBy,
            "sortOrder": sortOrder
        },
        "error_code": None,
        "error_message": None,
        "result": None,
        "screenshot_artifact_id": None,
        "ui_snapshot_artifact_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    actions.append(action)
    _save("session_actions.json", actions)

    # "Refresh" apps: in this offline datastore, we treat current device_apps rows as current;
    # still update last_scanned_at/updated_at to reflect refresh and satisfy business rule.
    dev_id = device.get("id")
    changed = False
    refreshed_at = now
    for a in apps:
        if isinstance(a, dict) and a.get("device_id") == dev_id:
            # ensure fields exist / update timestamps
            if a.get("last_scanned_at") != refreshed_at:
                a["last_scanned_at"] = refreshed_at
                a["updated_at"] = refreshed_at
                changed = True
    if changed:
        _save("device_apps.json", apps)

    # Filter installed apps
    rows = [a for a in apps if isinstance(a, dict) and a.get("device_id") == dev_id]
    if not includeSystemApps:
        # datastore contains "True"/"False" strings; accept booleans too
        def _is_system(v):
            if v is True: return True
            if v is False: return False
            if isinstance(v, str): return v.strip().lower() == "true"
            return False
        rows = [a for a in rows if not _is_system(a.get("is_system_app"))]

    # Sort
    reverse = (sortOrder == "desc")
    def _sv(v):
        if v is None:
            return ""
        if isinstance(v, bool):
            return "1" if v else "0"
        return v
    rows.sort(key=lambda r: (_sv(r.get(sortBy)), _sv(r.get("id"))), reverse=reverse)

    # Cursor semantics: cursor is an app id; unknown cursor should NOT be a hard error for this API surface.
    # Treat unknown cursor as "start from beginning" to relax strictness as per audit.
    start = 0
    if cursor:
        idx = next((i for i, r in enumerate(rows) if r.get("id") == cursor), None)
        if idx is not None:
            start = idx + 1

    page = rows[start:start + limit]
    next_cursor = page[-1].get("id") if len(page) == limit else None
    has_more = next_cursor is not None
    total = len(rows)

    # Update session last_action_at
    session["last_action_at"] = now
    session["updated_at"] = now
    _save("sessions.json", sessions)

    # Mark action success
    action["status"] = "succeeded"
    action["duration_ms"] = _duration_ms()
    action["updated_at"] = _now()
    action["result"] = {"returned": len(page), "total": total, "has_more": has_more, "next_cursor": next_cursor, "device_id": dev_id}
    _save("session_actions.json", actions)

    return {
        "apps": page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "device_id": dev_id,
        "session_id": session.get("id"),
        "sort_by": sortBy,
        "sort_order": sortOrder,
    }

def mobile_launch_app(packageName, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0522000" if __import__("os").path.isdir("./environment_mix/0522000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _duration_ms():
        return int((time.time() - t0) * 1000)
    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{time.time_ns()}"

    if not isinstance(packageName, str):
        return _err("VALIDATION_ERROR", "packageName must be a string")
    packageName = packageName.strip()
    if not packageName:
        return _err("VALIDATION_ERROR", "packageName must be a non-empty string")

    sessions = _load("sessions.json")
    devices = _load("devices.json")
    apps = _load("device_apps.json")
    actions = _load("session_actions.json")

    device_by_id = {d.get("id"): d for d in devices if isinstance(d, dict) and d.get("id")}
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and s.get("id") and s.get("device_id")]
    if not active_sessions:
        return _err("CONFLICT", "No device selected (no active session). Business rule: device-driving tools require an active session.")
    active_sessions.sort(key=lambda s: (s.get("last_action_at") or s.get("updated_at") or s.get("selected_at") or s.get("created_at") or ""), reverse=True)

    session = None
    device = None
    for s in active_sessions:
        d = device_by_id.get(s.get("device_id"))
        if d:
            session, device = s, d
            break
    if not session or not device:
        return _err("NOT_FOUND", "Selected device for the active session no longer exists.")

    if device.get("status") in ("offline", "disabled"):
        return _err("CONFLICT", "Selected device is not ready (offline/disabled). Business rule: device-driving tools cannot run when device is offline/disabled.", device_id=device.get("id"), device_status=device.get("status"))

    now = _now()
    action = {
        "id": _new_id("mob_act"),
        "session_id": session.get("id"),
        "device_id": device.get("id"),
        "tool_name": "mobile_launch_app",
