        return int((time.time() - t0) * 1000)
    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{time.time_ns()}"

    # Validate x/y (schema: number)
    if not isinstance(x, (int, float)) or isinstance(x, bool):
        return _err("VALIDATION_ERROR", "x must be a number")
    if not isinstance(y, (int, float)) or isinstance(y, bool):
        return _err("VALIDATION_ERROR", "y must be a number")

    sessions = _load("sessions.json")
    devices = _load("devices.json")
    actions = _load("session_actions.json")

    device_by_id = {d.get("id"): d for d in devices if isinstance(d, dict) and d.get("id")}
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and s.get("id") and s.get("device_id")]
    if not active_sessions:
        return _err("CONFLICT", "No device selected (no active session). Business rule: device-driving tools require an active session.")
    active_sessions.sort(key=lambda s: (s.get("last_action_at") or s.get("updated_at") or s.get("selected_at") or s.get("created_at") or ""), reverse=True)

    session = None
    device = None
    for s in active_sessions:
        d = device_by_id.get(s.get("device_id"))
        if d:
            session, device = s, d
            break
    if not session or not device:
        return _err("NOT_FOUND", "Selected device for the active session no longer exists.")

    if device.get("status") in ("offline", "disabled"):
        return _err("CONFLICT", "Selected device is not ready (offline/disabled). Business rule: device-driving tools cannot run when device is offline/disabled.", device_id=device.get("id"), device_status=device.get("status"))

    now = _now()
    action = {
        "id": _new_id("mob_act"),
        "session_id": session.get("id"),
        "device_id": device.get("id"),
        "tool_name": "mobile_click_on_screen_at_coordinates",
        "status": "running",
        "input": {"x": x, "y": y},
        "error_code": None,
        "error_message": None,
        "result": None,
        "screenshot_artifact_id": None,
        "ui_snapshot_artifact_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    actions.append(action)
    _save("session_actions.json", actions)

    # Business rule: enforce bounds when dimensions known; otherwise reject or resolve size via get_screen_size.
    # In this datastore, we reject if unknown (explicitly permitted by rule).
    w = device.get("screen_width_px")
    h = device.get("screen_height_px")
    if not (isinstance(w, int) and w > 0 and isinstance(h, int) and h > 0):
        action["status"] = "failed"
        action["error_code"] = "SCREEN_SIZE_UNKNOWN"
        action["error_message"] = "Business rule: click requires known screen dimensions; resolve screen size first via mobile_get_screen_size."
        action["duration_ms"] = _duration_ms()
        action["updated_at"] = _now()
        _save("session_actions.json", actions)
        return _err("VALIDATION_ERROR", "Cannot validate coordinates because device screen size is unknown. Business rule: click enforces bounds when size is known; otherwise resolve via mobile_get_screen_size first.", device_id=device.get("id"))

    # IMPORTANT: Accept edges correctly and be permissive about floats (cast like real drivers do).
    xi = int(round(x))
    yi = int(round(y))
    if not (0 <= xi < w and 0 <= yi < h):
        action["status"] = "failed"
        action["error_code"] = "COORDINATES_OUT_OF_BOUNDS"
        action["error_message"] = "Business rule: 0 <= x < screen_width_px and 0 <= y < screen_height_px when dimensions are known."
        action["duration_ms"] = _duration_ms()
        action["updated_at"] = _now()
        _save("session_actions.json", actions)
        return _err(
            "VALIDATION_ERROR",
            f"Coordinates out of bounds. Business rule: 0 <= x < screen_width_px and 0 <= y < screen_height_px when dimensions are known.",
