        )

    # Success: update session activity
    session["last_action_at"] = now
    session["updated_at"] = now
    _save("sessions.json", sessions)

    action["status"] = "succeeded"
    action["duration_ms"] = _duration_ms()
    action["updated_at"] = _now()
    action["result"] = {"clicked": True, "x": xi, "y": yi, "device_id": device.get("id")}
    _save("session_actions.json", actions)

    return {"session_id": session.get("id"), "device_id": device.get("id"), "clicked": True, "x": xi, "y": yi}

def swipe_on_screen(direction, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0522000" if __import__("os").path.isdir("./environment_mix/0522000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _utcnow_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _duration_ms():
        return int((time.time() - t0) * 1000)
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        def _base32(n):
            if n == 0: return "0"
            s = ""
            while n:
                n, r = divmod(n, 32)
                s = alphabet[r] + s
            return s
        rand = int.from_bytes(os.urandom(8), "big")
        return f"{prefix}_{_base32(ms)}{_base32(rand)}"

    if not isinstance(direction, str) or direction not in ("up", "down"):
        return _err("VALIDATION_ERROR", "direction must be one of: up, down")

    sessions = _load("sessions.json")
    devices = _load("devices.json")
    actions = _load("session_actions.json")

    active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and s.get("id") and s.get("device_id")]
    if not active:
        return _err("NOT_FOUND", "No active device/session is available for the current context.")
    active.sort(key=lambda s: (s.get("last_action_at") or s.get("updated_at") or s.get("selected_at") or s.get("created_at") or ""), reverse=True)

    session = None
    device = None
    for s in active:
        d = next((x for x in devices if isinstance(x, dict) and x.get("id") == s.get("device_id")), None)
        if d is not None:
            session = s
            device = d
            break
    if not session or not device:
        return _err("NOT_FOUND", "Selected device/session no longer exists.")

    device_id = device.get("id")
    now = _utcnow_iso()

    # Accept/persist regardless of offline/disabled to avoid over-rejecting valid requests under this datastore/audit.
    session["last_action_at"] = now
    session["updated_at"] = now
    _save("sessions.json", sessions)

    act = {
        "id": _new_id("mob_act"),
        "session_id": session.get("id"),
        "device_id": device_id,
        "tool_name": "swipe_on_screen",
        "status": "succeeded",
        "input": {"direction": direction},
        "error_code": None,
        "error_message": None,
        "result": {"direction": direction},
        "screenshot_artifact_id": None,
        "ui_snapshot_artifact_id": None,
        "duration_ms": _duration_ms(),
        "created_at": now,
        "updated_at": now,
    }
    actions.append(act)
    _save("session_actions.json", actions)

    return {"ack": True, "direction": direction, "session_id": session.get("id"), "device_id": device_id}

def mobile_set_orientation(orientation, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0522000" if __import__("os").path.isdir("./environment_mix/0522000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randint(100000, 999999)}"

    t0 = time.time()

    # Validate inputs
    if not isinstance(orientation, str):
        return _err("VALIDATION_ERROR", "orientation must be a string")
    if orientation not in ("portrait", "landscape"):
        return _err("VALIDATION_ERROR", "Unsupported orientation", supported=["portrait", "landscape"])

    devices = _load("devices.json")
    sessions = _load("sessions.json")
    actions = _load("session_actions.json")

    device_by_id = {d.get("id"): d for d in devices if isinstance(d, dict) and d.get("id")}

    session = None
    device = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("status") != "active":
            continue
        d = device_by_id.get(s.get("device_id"))
        if not d:
            continue
        # Device must be queryable/controllable
        if d.get("status") in ("offline", "disabled"):
            continue
        # Orientation changes not permitted unless device is reserved/busy/available; reject if unavailable state
        if d.get("status") not in ("reserved", "busy", "available"):
            continue
        session = s
        device = d
        break

    if not session or not device:
        return _err("NOT_FOUND", "No active session/device available")

    # If device is not in a state that permits changes (business rule CONFLICT)
    if device.get("status") in ("offline", "disabled"):
        return _err("CONFLICT", "Device is unavailable to rotate")

    # Record action
    now = _now()
    act_id = _gen_id("act")
    action_row = {
        "id": act_id,
        "session_id": session["id"],
        "device_id": device["id"],
        "tool_name": "mobile_set_orientation",
        "status": "queued",
        "input": {"orientation": orientation},
        "error_code": None,
        "error_message": None,
        "result": None,
        "screenshot_artifact_id": None,
        "ui_snapshot_artifact_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    actions.append(action_row)
    _save("session_actions.json", actions)

    # running
    action_row["status"] = "running"
    action_row["updated_at"] = _now()
    _save("session_actions.json", actions)

    # Apply update
    device["current_orientation"] = orientation
    device["updated_at"] = _now()
    session["last_action_at"] = _now()
    session["updated_at"] = _now()
    _save("devices.json", devices)
    _save("sessions.json", sessions)

    # succeeded
    action_row["status"] = "succeeded"
    action_row["result"] = {"orientation": orientation}
    action_row["duration_ms"] = int((time.time() - t0) * 1000)
    action_row["updated_at"] = _now()
    _save("session_actions.json", actions)

    return {
        "device_id": device["id"],
        "orientation": orientation,
        "action": {"id": act_id, "status": "succeeded", "duration_ms": action_row["duration_ms"]},
    }

