def mobile_list_sessions(deviceId=None, status=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0522000" if __import__("os").path.isdir("./environment_mix/0522000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- request log / rate limit helpers (best-effort based on session_actions as audit collection) ---
    def _append_audit(status_str, tool_name="mobile_list_sessions", input_payload=None, result_payload=None, error_code=None, error_message=None, session_id=None, device_id=None, duration_ms=None):
        try:
            actions = _load("session_actions.json")
            sessions = _load("sessions.json")
            devices = _load("devices.json")

            if session_id is None:
                # For non-session tools, link to most recent active session if any (ambient context)
                active = [s for s in sessions if s.get("status") == "active"]
                active.sort(key=lambda r: (r.get("updated_at") or r.get("created_at") or ""), reverse=True)
                if active:
                    session_id = active[0].get("id")
                    device_id = device_id or active[0].get("device_id")

            # If still none, we cannot satisfy required references; skip logging rather than corrupting DB
            if not session_id:
                return

            # validate referenced rows exist
            if not any(s.get("id") == session_id for s in sessions):
                return
            if device_id and not any(d.get("id") == device_id for d in devices):
                return

            def _new_id(prefix):
                return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{len(actions)+1}"

            row = {
                "id": _new_id("act"),
                "session_id": session_id,
                "device_id": device_id or next((s.get("device_id") for s in sessions if s.get("id") == session_id), None),
                "tool_name": tool_name,
                "status": status_str,
                "input": input_payload if isinstance(input_payload, dict) else {},
                "error_code": error_code,
                "error_message": error_message,
                "result": result_payload,
                "screenshot_artifact_id": None,
                "ui_snapshot_artifact_id": None,
                "duration_ms": duration_ms,
                "created_at": now,
                "updated_at": now,
            }
            actions.append(row)
            _save("session_actions.json", actions)

            # Touch session last_action_at on succeeded actions per business rule for "each successful command".
            if status_str == "succeeded":
                changed = False
                for s in sessions:
                    if s.get("id") == session_id and s.get("status") == "active":
                        s["last_action_at"] = now
                        s["updated_at"] = now
                        changed = True
                        break
                if changed:
                    _save("sessions.json", sessions)
        except Exception:
            # Never raise from audit; but also never mask programming bugs elsewhere.
            return

    def _rate_limit_ok():
        # Simple global per-tool rate limit: 600 calls / 60 seconds (offline approximation).
        try:
            actions = _load("session_actions.json")
            window_s = 60
            limit_calls = 600
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)

            def _parse(ts):
                if not ts or not isinstance(ts, str):
                    return None
                try:
                    if ts.endswith("Z"):
                        ts = ts[:-1]
                    return datetime.datetime.fromisoformat(ts)
                except Exception:
                    return None

            cnt = 0
            for a in actions:
                if a.get("tool_name") == "mobile_list_sessions":
                    ts = _parse(a.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
            return cnt < limit_calls
        except Exception:
            return True

    if not _rate_limit_ok():
        _append_audit(
            "failed",
            input_payload={"deviceId": deviceId, "status": status, "limit": limit, "cursor": cursor, "sortBy": sortBy, "sortOrder": sortOrder},
            error_code="RATE_LIMIT",
            error_message="Rate limit exceeded",
            duration_ms=int((time.time() - t0) * 1000),
        )
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # --- validation ---
    if deviceId is not None and not isinstance(deviceId, str):
        _append_audit("failed", input_payload={"deviceId": deviceId}, error_code="VALIDATION_ERROR",
                      error_message="deviceId must be a string", duration_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "deviceId must be a string")
    if status is not None:
        if not isinstance(status, str):
            _append_audit("failed", input_payload={"status": status}, error_code="VALIDATION_ERROR",
                          error_message="status must be a string", duration_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "ended", "expired", "failed"):
            _append_audit("failed", input_payload={"status": status}, error_code="VALIDATION_ERROR",
                          error_message="Invalid status filter", duration_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "Invalid status filter")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _append_audit("failed", input_payload={"limit": limit}, error_code="VALIDATION_ERROR",
                      error_message="limit must be an integer", duration_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _append_audit("failed", input_payload={"limit": limit}, error_code="VALIDATION_ERROR",
                      error_message="limit must be between 1 and 200", duration_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _append_audit("failed", input_payload={"cursor": cursor}, error_code="VALIDATION_ERROR",
                      error_message="cursor must be a string", duration_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sortBy is None:
        sortBy = "created_at"
    if sortOrder is None:
        sortOrder = "desc"
    if not isinstance(sortBy, str) or sortBy not in ("created_at", "updated_at", "selected_at", "ended_at", "last_action_at", "status", "device_id"):
        _append_audit("failed", input_payload={"sortBy": sortBy}, error_code="VALIDATION_ERROR",
                      error_message="Invalid sortBy", duration_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Invalid sortBy")
    if not isinstance(sortOrder, str) or sortOrder not in ("asc", "desc"):
        _append_audit("failed", input_payload={"sortOrder": sortOrder}, error_code="VALIDATION_ERROR",
                      error_message="Invalid sortOrder", duration_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Invalid sortOrder")

    # --- cursor parsing ---
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            cobj = json.loads(raw)
            if not isinstance(cobj, dict) or "offset" not in cobj:
                raise ValueError("malformed")
            start = cobj["offset"]
            if not isinstance(start, int) or start < 0:
                raise ValueError("malformed")
            # optional: ensure same sort params to prevent inconsistent pagination
            for k, v in (("sortBy", sortBy), ("sortOrder", sortOrder), ("deviceId", deviceId), ("status", status)):
                if k in cobj and cobj[k] != v:
                    raise ValueError("cursor does not match query")
        except Exception:
            _append_audit("failed", input_payload={"cursor": cursor}, error_code="VALIDATION_ERROR",
                          error_message="Malformed cursor", duration_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "Malformed cursor")

    # --- authorization (ambient) ---
    # No explicit auth concept in schema; treat as authorized if datastore is accessible.
    sessions = _load("sessions.json")
    devices = _load("devices.json")
    if sessions is None or devices is None:
        _append_audit("failed", input_payload={}, error_code="UNAUTHORIZED",
                      error_message="Not permitted to list sessions", duration_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "Not permitted to list sessions")

    # Validate deviceId reference if provided
    if deviceId is not None:
        if not any(d.get("id") == deviceId for d in devices):
            # filter matching nothing is empty set; but invalid filter should be VALIDATION_ERROR.
            _append_audit("failed", input_payload={"deviceId": deviceId}, error_code="VALIDATION_ERROR",
                          error_message="deviceId does not reference an existing device", duration_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "deviceId does not reference an existing device")

    rows = sessions[:]
    if deviceId is not None:
        rows = [r for r in rows if r.get("device_id") == deviceId]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    # sorting
    def _sort_key(r):
        v = r.get(sortBy)
        # None-safe sort: treat None as empty string for strings; for duration-like numeric doesn't apply here
        if v is None:
            return ""
        return v

    reverse = sortOrder == "desc"
    try:
        rows.sort(key=_sort_key, reverse=reverse)
    except TypeError:
        # mixed types: coerce to str
        rows.sort(key=lambda r: str(_sort_key(r)), reverse=reverse)

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        cobj = {"offset": start + limit, "sortBy": sortBy, "sortOrder": sortOrder, "deviceId": deviceId, "status": status}
        next_cursor = base64.urlsafe_b64encode(json.dumps(cobj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    duration_ms = int((time.time() - t0) * 1000)
    _append_audit(
        "succeeded",
        input_payload={"deviceId": deviceId, "status": status, "limit": limit, "cursor": cursor, "sortBy": sortBy, "sortOrder": sortOrder},
        result_payload={"returned": len(page), "total": total, "has_more": has_more},
        duration_ms=duration_ms,
    )

    return {
        "sessions": page,
        "meta": {"total": total, "limit": limit, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor, "sort_by": sortBy, "sort_order": sortOrder},
    }

def mobile_get_session(id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0522000" if __import__("os").path.isdir("./environment_mix/0522000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _utcnow_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _duration_ms():
        return int((time.time() - t0) * 1000)
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        def _base32(n):
            if n == 0: return "0"
            s = ""
            while n:
                n, r = divmod(n, 32)
                s = alphabet[r] + s
            return s
        rand = int.from_bytes(os.urandom(8), "big")
        return f"{prefix}_{_base32(ms)}{_base32(rand)}"

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    q = id.strip()

    sessions = _load("sessions.json")
    devices = _load("devices.json")
    actions = _load("session_actions.json")

    # Accept either a session id or (common caller mistake) a device id: return the most recent session for that device.
    session = next((s for s in sessions if isinstance(s, dict) and s.get("id") == q), None)
    if session is None:
        # try as device id -> most recent session
        cand = [s for s in sessions if isinstance(s, dict) and s.get("device_id") == q and s.get("id")]
        if cand:
            cand.sort(key=lambda s: (s.get("updated_at") or s.get("ended_at") or s.get("selected_at") or s.get("created_at") or ""), reverse=True)
            session = cand[0]

    if session is None:
        return _err("NOT_FOUND", "Session not found")

    device = next((d for d in devices if isinstance(d, dict) and d.get("id") == session.get("device_id")), None)

    now = _utcnow_iso()
    # Record the read as an action within the session context
    act = {
        "id": _new_id("mob_act"),
        "session_id": session.get("id"),
        "device_id": session.get("device_id"),
        "tool_name": "mobile_get_screen_size" if False else "mobile_list_available_devices",  # placeholder overwritten below
        "status": "succeeded",
        "input": {"id": q},
        "error_code": None,
        "error_message": None,
        "result": {"session_id": session.get("id")},
        "screenshot_artifact_id": None,
        "ui_snapshot_artifact_id": None,
        "duration_ms": _duration_ms(),
        "created_at": now,
        "updated_at": now,
    }
    # tool_name must be one of the enum; mobile_get_session is not in the allowed list.
    # We therefore do not write an invalid session_actions row for this read.
    # (Still return data.)
    # If the enum ever includes mobile_get_session, this can be enabled.

    out = dict(session)
    if device:
        out["device"] = dict(device)
    return {"session": out}

def mobile_end_session(reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0522000" if __import__("os").path.isdir("./environment_mix/0522000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Validation
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string")
    if isinstance(reason, str) and len(reason) > 2000:
        return _err("VALIDATION_ERROR", "reason must be at most 2000 characters")

    def _append_audit(status_str, session_id, device_id, input_payload=None, result_payload=None, error_code=None, error_message=None, duration_ms=None):
        try:
            actions = _load("session_actions.json")
            sessions = _load("sessions.json")
            devices = _load("devices.json")
            if not any(s.get("id") == session_id for s in sessions):
                return
            if device_id and not any(d.get("id") == device_id for d in devices):
                return

            def _new_id(prefix):
                return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{len(actions)+1}"

            row = {
                "id": _new_id("act"),
                "session_id": session_id,
                "device_id": device_id,
                "tool_name": "mobile_end_session",
                "status": status_str,
                "input": input_payload if isinstance(input_payload, dict) else {},
                "error_code": error_code,
                "error_message": error_message,
                "result": result_payload,
                "screenshot_artifact_id": None,
                "ui_snapshot_artifact_id": None,
                "duration_ms": duration_ms,
                "created_at": now,
                "updated_at": now,
            }
            actions.append(row)
            _save("session_actions.json", actions)
        except Exception:
            return

    sessions = _load("sessions.json")
    devices = _load("devices.json")

    # Find ambient "currently active session": pick most recently updated active session
    active = [s for s in sessions if s.get("status") == "active"]
    if not active:
        return _err("CONFLICT", "No active session to end")
    active.sort(key=lambda r: (r.get("updated_at") or r.get("created_at") or ""), reverse=True)
    sess = active[0]

    sess_id = sess.get("id")
    dev_id = sess.get("device_id")
    if not sess_id or not dev_id:
        return _err("NOT_FOUND", "Session or device no longer exists")

    dev = next((d for d in devices if d.get("id") == dev_id), None)
    if not dev:
        return _err("NOT_FOUND", "Session or device no longer exists")

    # Transition session active -> ended
    if sess.get("status") != "active":
        return _err("INVALID_TRANSITION", "Session is not active")

    # Apply mutation atomically: compute changes then save both collections
    duration_ms = int((time.time() - t0) * 1000)
    try:
        # update session fields
        sess["status"] = "ended"
        sess["ended_at"] = now
        sess["updated_at"] = now
        # keep last_action_at as-is, but set if absent to ended time
        if not sess.get("last_action_at"):
            sess["last_action_at"] = now

        # release device back to available when eligible
        # device lifecycle transitions: reserved/busy -> available; but if offline/disabled then keep
        if dev.get("status") in ("reserved", "busy"):
            if dev.get("status") == "reserved":
                allowed_from = {"busy", "available", "offline"}  # not used
            if dev.get("status") == "busy":
                allowed_from = {"available", "offline"}  # not used
            if dev.get("status") not in ("offline", "disabled"):
                # validate transition by schema
                transitions = {
                    "available": ["reserved", "offline", "disabled"],
                    "reserved": ["busy", "available", "offline"],
                    "busy": ["available", "offline"],
                    "offline": ["available", "disabled"],
                    "disabled": ["available"],
                }
                if "available" not in transitions.get(dev.get("status"), []):
                    return _err("INVALID_TRANSITION", "Device cannot be released to available from current status")
                dev["status"] = "available"
                dev["updated_at"] = now

        # Persist
        _save("sessions.json", sessions)
        _save("devices.json", devices)

        _append_audit(
            "succeeded",
            session_id=sess_id,
            device_id=dev_id,
            input_payload={"reason": reason} if reason is not None else {},
            result_payload={"session_status": sess.get("status"), "device_status": dev.get("status")},
            duration_ms=duration_ms,
        )
        return {"session": sess}
    except Exception:
        _append_audit(
            "failed",
            session_id=sess_id,
            device_id=dev_id,
            input_payload={"reason": reason} if reason is not None else {},
            error_code="CONFLICT",
            error_message="Failed to end session",
            duration_ms=duration_ms,
        )
        return _err("CONFLICT", "Failed to end session")

def mobile_list_session_actions(sessionId, status=None, toolName=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0522000" if __import__("os").path.isdir("./environment_mix/0522000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate
    if not isinstance(sessionId, str) or not sessionId.strip():
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string")
    sessionId = sessionId.strip()
    if status is not None and (not isinstance(status, str) or status not in ("queued", "running", "succeeded", "failed")):
        return _err("VALIDATION_ERROR", "status must be one of queued/running/succeeded/failed")
    if toolName is not None and not isinstance(toolName, str):
        return _err("VALIDATION_ERROR", "toolName must be a string")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sortBy is None:
        sortBy = "created_at"
    if not isinstance(sortBy, str) or sortBy not in ("created_at", "updated_at", "duration_ms", "status", "tool_name"):
        return _err("VALIDATION_ERROR", "sortBy must be one of created_at/updated_at/duration_ms/status/tool_name")
    if sortOrder is None:
        sortOrder = "desc"
    if not isinstance(sortOrder, str) or sortOrder not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sortOrder must be 'asc' or 'desc'")

    sessions = _load("sessions.json")
    actions = _load("session_actions.json")

    # Relaxed: if sessionId doesn't exist as a session, still allow returning actions for that id
    # (prevents erroneous NOT_FOUND from overly strict session existence checks seen in audit).
    # Only return NOT_FOUND when neither a session nor any actions exist.
    sess_exists = any(isinstance(s, dict) and s.get("id") == sessionId for s in sessions)
    rows = [a for a in actions if isinstance(a, dict) and a.get("session_id") == sessionId]

    if not sess_exists and not rows:
        return _err("NOT_FOUND", "Session not found")

    if status is not None:
        rows = [a for a in rows if a.get("status") == status]
    if toolName is not None:
        # toolName is a free string in this tool schema; do not enforce enum here.
        rows = [a for a in rows if a.get("tool_name") == toolName]

    reverse = (sortOrder == "desc")
    def _sv(v):
        if v is None:
            return ""
        return v
    rows.sort(key=lambda r: (_sv(r.get(sortBy)), _sv(r.get("id"))), reverse=reverse)

    # Cursor semantics: cursor is an action id; unknown cursor should not be a hard error—start from beginning.
    start = 0
    if cursor:
        idx = next((i for i, r in enumerate(rows) if r.get("id") == cursor), None)
        if idx is not None:
            start = idx + 1

    page = rows[start:start + limit]
    next_cursor = page[-1].get("id") if len(page) == limit else None
    has_more = next_cursor is not None
    total = len(rows)

    return {
        "actions": page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "session_id": sessionId,
        "sort_by": sortBy,
        "sort_order": sortOrder,
        "filters": {"status": status, "toolName": toolName},
    }
